mapper.update:
UPDATE kb_file
SET status = #{status},
    process_stage = #{processStage},
    progress = #{progress},
    error_message = #{errorMessage}
WHERE id = #{id}

mapper.select:
SELECT * FROM kb_file
WHERE status = 'FAILED'
  AND process_attempts < #{maxAttempts}
  AND next_retry_time IS NOT NULL
  AND next_retry_time <= #{now}
ORDER BY next_retry_time ASC
LIMIT #{limit}

mapper.update:
UPDATE kb_file
SET process_attempts = 0, next_retry_time = NULL
WHERE id = #{id}
